insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Definições: sistema de computador é qualquer aparelho ou conjunto interconectado que processa dados eletronicamente por um programa; dado de computador é qualquer representação de fatos, informações ou conceitos adequada ao processamento; provedor de serviços é qualquer entidade que permite aos usuários se comunicarem por sistema de computador, ou que processa ou armazena dados em nome desses serviços; e dados de tráfego são os dados de uma comunicação que indicam origem, destino, caminho, hora, data, extensão, duração ou tipo de serviço.', '["Sistema de computador.","Dado de computador.","Provedor de serviços (comunicação ou processamento e armazenamento).","Dados de tráfego: origem, destino, caminho, hora, data, extensão, duração e tipo de serviço."]'::jsonb, '["Dados de tráfego NÃO incluem o conteúdo da comunicação."]'::jsonb, 'Os registros de data, hora e origem de um e-mail são dados de tráfego.', '["Assertiva que inclui o conteúdo da mensagem nos dados de tráfego erra."]'::jsonb, '[{"termo":"Dados de tráfego","significado":"Metadados da comunicação, como origem, destino e horário."}]'::jsonb, '["Artigo 16","Artigo 20"]'::jsonb, 'under_review', 'claude'
