insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Uso indevido de aparelhagem: cada Parte tipificará, quando dolosas e não autorizadas, a produção, venda, aquisição para uso, importação, distribuição ou disponibilização de aparelho ou programa desenvolvido para cometer os crimes dos artigos 2 a 5, e de senhas ou códigos de acesso para esse fim; e a posse desses instrumentos com a intenção de usá-los. A Parte pode exigir um número mínimo de instrumentos. Não há crime quando a conduta não se destina a esses crimes, como em testes autorizados ou proteção de sistema. Cada Parte pode reservar-se o direito de não aplicar o parágrafo 1, mas não quanto à venda ou distribuição de senhas e códigos de acesso.', '["Aparelho ou programa desenvolvido para cometer crimes dos artigos 2 a 5.","Senhas e códigos de acesso para esse fim.","Posse com intenção de uso.","Exclusão: testes autorizados e proteção de sistemas.","Reserva possível, exceto para venda e distribuição de senhas."]'::jsonb, '["Testes autorizados (pentest) NÃO são crime."]'::jsonb, 'Vender um programa feito para invadir sistemas é uso indevido de aparelhagem.', '["Assertiva que criminaliza o teste autorizado de segurança erra: o parágrafo 2 o exclui."]'::jsonb, '[]'::jsonb, '["Artigos 2 a 5"]'::jsonb, 'under_review', 'claude'
