insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Violação de direitos autorais e correlatos: cada Parte tipificará como crimes a violação de direitos autorais e de direitos correlatos, conforme as obrigações assumidas nos tratados internacionais indicados, com exceção dos direitos morais, quando cometida intencionalmente, em escala comercial e por meio de um sistema de computador. A Parte pode reservar-se o direito de não impor responsabilidade criminal em circunstâncias limitadas, desde que haja outros remédios jurídicos eficazes e que a reserva não prejudique suas obrigações internacionais.', '["Violação de direitos autorais e correlatos.","Intencional, em escala comercial e por sistema de computador.","Exclui direitos morais.","Reserva em circunstâncias limitadas."]'::jsonb, '["Exige ESCALA COMERCIAL e meio informático."]'::jsonb, 'Vender cópias piratas de software pela internet em larga escala é violação punível.', '["Assertiva que criminaliza qualquer cópia privada de baixa escala erra: exige escala comercial."]'::jsonb, '[]'::jsonb, '["Lei de Direitos Autorais"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'budapeste' and u.unit_key = 'conven-o-artigo-10'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Tentativa, auxílio ou instigação: cada Parte tipificará o auxílio, a instigação ou a incitação dolosos à prática dos crimes dos artigos 2 a 10, quando o favorecedor tenha a intenção de que sejam cometidos, e a tentativa dolosa dos crimes dos artigos 3 a 5, 7, 8 e do parágrafo 1, alíneas a e c, do artigo 9. A Parte pode reservar-se o direito de não aplicar a punição da tentativa.', '["Auxílio, instigação ou incitação dolosos aos crimes dos artigos 2 a 10.","Tentativa de alguns crimes.","Reserva para a tentativa."]'::jsonb, '["A tentativa não é exigida para todos os crimes."]'::jsonb, 'Quem instiga outra pessoa a invadir um sistema pratica a conduta do artigo 11.', '["Assertiva que obriga punir a tentativa de todos os crimes da Convenção erra."]'::jsonb, '[]'::jsonb, '["Artigos 2 a 10"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'budapeste' and u.unit_key = 'conven-o-artigo-11'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Responsabilidade da pessoa jurídica: cada Parte assegurará que pessoas jurídicas possam ser responsabilizadas pelos crimes da Convenção cometidos em seu benefício por pessoa física em posição de direção, com base no poder de representação, na autoridade de decidir em nome da empresa ou de exercer controle interno. Também responde a empresa quando a falta de supervisão ou controle possibilitar o crime por pessoa sob sua autoridade. A responsabilidade pode ser civil, criminal ou administrativa, e não exclui a responsabilidade criminal das pessoas naturais.', '["Responsabilidade por crimes em benefício da pessoa jurídica.","Pessoa em posição de direção.","Falta de supervisão também gera responsabilidade.","Civil, criminal ou administrativa.","Sem prejuízo da pessoa natural."]'::jsonb, '["A responsabilidade da empresa pode ser civil, criminal OU administrativa."]'::jsonb, 'A empresa responde quando o diretor comanda uma fraude informática em seu benefício.', '["Assertiva que exclui a responsabilidade da pessoa natural quando a empresa responde erra."]'::jsonb, '[]'::jsonb, '["Artigo 13"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'budapeste' and u.unit_key = 'conven-o-artigo-12'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Sanções e medidas: cada Parte assegurará que os crimes dos artigos 2 a 11 sejam punidos por sanções criminais eficazes, adequadas e dissuasivas, que incluam a privação de liberdade. As pessoas jurídicas responsáveis estarão sujeitas a sanções penais ou não penais eficazes, proporcionais e dissuasivas, inclusive penas pecuniárias.', '["Sanções eficazes, adequadas e dissuasivas.","Inclui privação de liberdade para pessoas físicas.","Pessoas jurídicas: sanções penais ou não penais, inclusive multa."]'::jsonb, '["Pessoa jurídica: sanções proporcionais, incluindo pecuniárias."]'::jsonb, 'A lei prevê prisão para o hacker e multa para a empresa responsável.', '["Assertiva que dispensa a privação de liberdade para as pessoas físicas erra."]'::jsonb, '[]'::jsonb, '["Artigo 12"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'budapeste' and u.unit_key = 'conven-o-artigo-13'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Âmbito dos dispositivos processuais: cada Parte adotará as medidas para estabelecer os poderes e procedimentos desta seção com o fim de promover investigações ou processos criminais. Salvo previsão específica, os poderes se aplicam aos crimes dos artigos 2 a 11, a outros crimes cometidos por meio de sistema de computador e à coleta de provas eletrônicas de qualquer crime. A Parte pode reservar-se o direito de aplicar algumas medidas só a certos crimes, e de excluir comunicações de sistemas fechados de grupo restrito, sem rede pública.', '["Poderes e procedimentos para investigações e processos criminais.","Aplicam-se aos crimes dos artigos 2 a 11, a outros crimes informáticos e à prova eletrônica.","Reservas possíveis."]'::jsonb, '["Alcança também a coleta de provas eletrônicas de QUALQUER crime."]'::jsonb, 'Os poderes processuais valem para obter prova digital de um homicídio.', '["Assertiva que restringe os poderes processuais aos crimes dos artigos 2 a 11 erra."]'::jsonb, '[{"termo":"Prova eletrônica","significado":"Prova obtida em meio digital."}]'::jsonb, '["Artigo 15"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'budapeste' and u.unit_key = 'conven-o-artigo-14'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Condições e garantias: os poderes e procedimentos desta seção sujeitam-se às condições e garantias da legislação interna, com proteção adequada aos direitos humanos e às liberdades públicas, inclusive os decorrentes de tratados de direitos humanos, e incorporarão o princípio da proporcionalidade. Incluem, quando apropriado, controle judicial ou supervisão independente, fundamentação, e limitação do âmbito e da duração. Cada Parte levará em conta o impacto sobre os direitos e legítimos interesses de terceiros.', '["Proteção dos direitos humanos e das liberdades públicas.","Proporcionalidade.","Controle judicial ou supervisão independente.","Fundamentação e limites de âmbito e duração.","Impacto sobre terceiros."]'::jsonb, '["Salvaguardas obrigatórias aos poderes investigativos."]'::jsonb, 'A quebra de sigilo digital exige fundamentação e limites de duração.', '["Assertiva que dispensa o princípio da proporcionalidade nos poderes processuais erra."]'::jsonb, '[]'::jsonb, '["Artigo 14"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'budapeste' and u.unit_key = 'conven-o-artigo-15'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Preservação expedita de dados de computador: cada Parte permitirá que a autoridade competente ordene ou obtenha a rápida preservação de dados especificados, incluindo dados de tráfego, armazenados em sistema de computador, especialmente quando houver risco de perda ou modificação. A ordem a uma pessoa para preservar dados obriga a mantê-los íntegros pelo tempo necessário, até o máximo de 90 dias, para permitir à autoridade buscar sua revelação, podendo a Parte prever renovação. O detentor deve manter em sigilo o início do procedimento investigativo. Aplicam-se os Artigos 14 e 15.', '["Preservação rápida de dados específicos, inclusive de tráfego.","Prazo máximo de 90 dias, com possível renovação.","Sigilo do procedimento.","Sujeita às garantias dos Artigos 14 e 15."]'::jsonb, '["Preservação por até 90 dias; NÃO é revelação do conteúdo."]'::jsonb, 'A autoridade ordena ao provedor que preserve os registros por noventa dias, até obter a ordem de revelação.', '["Assertiva que fixa em 30 dias o prazo máximo de preservação erra: são 90 dias."]'::jsonb, '[]'::jsonb, '["Artigo 17"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'budapeste' and u.unit_key = 'conven-o-artigo-16'
