insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Preservação expedita e revelação parcial de dados de tráfego: cada Parte assegurará que a rápida preservação de dados de tráfego seja possível independentemente do número de provedores envolvidos na transmissão, e a rápida revelação à autoridade competente de dados de tráfego suficientes para identificar os provedores e o caminho da comunicação. Sujeito aos Artigos 14 e 15.', '["Preservação independentemente do número de provedores.","Revelação rápida de dados suficientes para identificar provedores e caminho."]'::jsonb, '["Revelação PARCIAL: só o necessário para identificar provedores e caminho."]'::jsonb, 'A autoridade descobre por quais provedores passou a comunicação.', '["Assertiva que obriga a revelar todo o conteúdo da comunicação erra: a revelação é de dados de tráfego suficientes."]'::jsonb, '[]'::jsonb, '["Artigo 16"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'budapeste' and u.unit_key = 'conven-o-artigo-17'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Ordem de exibição: cada Parte dará poderes às autoridades para ordenar a qualquer pessoa residente em seu território que entregue dados de computador especificados sob seu controle, e a qualquer provedor de serviço que atue em seu território que entregue informações cadastrais de assinantes. Informações cadastrais do assinante são as informações em poder do provedor, exceto dados de tráfego e conteúdo, que revelem o tipo de serviço, a identidade, o endereço, o telefone, os dados de pagamento e o local de instalação do equipamento. Sujeito aos Artigos 14 e 15.', '["Ordem a pessoa residente para entregar dados especificados.","Ordem ao provedor para entregar informações cadastrais de assinantes.","Informações cadastrais excluem dados de tráfego e conteúdo."]'::jsonb, '["Dados CADASTRAIS: não incluem tráfego nem conteúdo."]'::jsonb, 'A autoridade pede ao provedor o nome e o endereço do assinante de um endereço de rede.', '["Assertiva que inclui o conteúdo das mensagens nas informações cadastrais erra."]'::jsonb, '[]'::jsonb, '["Artigo 1"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'budapeste' and u.unit_key = 'conven-o-artigo-18'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Busca e apreensão de dados de computador: cada Parte dará poderes às autoridades para buscar ou investigar, em seu território, qualquer sistema de computador ou parte dele e os dados nele armazenados, e qualquer meio de armazenamento de dados. Se houver fundadas razões para supor que os dados estão em outro sistema do território, acessível a partir do primeiro, a autoridade poderá estender prontamente a busca. As Partes dão poderes para apreender ou proteger sistemas e meios de armazenamento, fazer e guardar cópia dos dados, manter a integridade e tornar os dados inacessíveis ou removê-los, e para determinar que quem conheça o funcionamento do sistema forneça as informações necessárias.', '["Busca em sistemas e meios de armazenamento no território.","Extensão da busca a outro sistema acessível.","Apreensão, cópia, integridade e remoção de dados.","Colaboração de quem conhece o sistema."]'::jsonb, '["A extensão da busca exige fundadas razões e acesso legal a partir do sistema inicial."]'::jsonb, 'A polícia busca o computador do investigado e estende a busca ao armazenamento em nuvem acessível dele.', '["Assertiva que proíbe a cópia dos dados apreendidos erra: a Convenção autoriza fazer e guardar cópia."]'::jsonb, '[]'::jsonb, '["Artigo 15"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'budapeste' and u.unit_key = 'conven-o-artigo-19'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Obtenção de dados de tráfego em tempo real: cada Parte dará poderes às autoridades para coletar ou gravar, por meios técnicos, dados de tráfego em tempo real vinculados a comunicações específicas ocorridas em seu território, e para obrigar o provedor, nos limites de sua capacidade técnica, a reunir e gravar esses dados ou a cooperar com as autoridades. Quando a Parte, por princípios de seu sistema jurídico, não puder adotar a coleta direta, poderá substituí-la por medidas que assegurem a obtenção em tempo real por meios técnicos em seu território. O provedor mantém sigilo da operação. Aplicam-se os Artigos 14 e 15.', '["Coleta de dados de tráfego em tempo real.","Obrigação de cooperação do provedor.","Substituição possível por outras medidas.","Sigilo do provedor."]'::jsonb, '["Aqui são dados de TRÁFEGO, e não de conteúdo (conteúdo: Artigo 21)."]'::jsonb, 'A autoridade acompanha em tempo real os horários e destinos das comunicações do investigado.', '["Assertiva que autoriza, pelo Artigo 20, o acesso ao conteúdo das comunicações erra: ele trata de dados de tráfego."]'::jsonb, '[]'::jsonb, '["Artigo 21"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'budapeste' and u.unit_key = 'conven-o-artigo-20'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Interceptação de dados de conteúdo: cada Parte, em relação a um conjunto de crimes graves a serem especificados pela legislação interna, dará poderes às autoridades para coletar ou gravar, em tempo real, o conteúdo de comunicações específicas ocorridas em seu território por sistema de computador, e para compelir o provedor, nos limites de sua capacidade técnica, a coletar, gravar ou cooperar. Quando a Parte não puder adotar a coleta direta, poderá substituí-la por medidas equivalentes. O provedor mantém sigilo. Aplicam-se os Artigos 14 e 15.', '["Interceptação do conteúdo em tempo real.","Apenas para crimes graves especificados em lei interna.","Cooperação e sigilo do provedor."]'::jsonb, '["Conteúdo: só para CRIMES GRAVES definidos na lei interna."]'::jsonb, 'A autoridade, com ordem legal, intercepta o conteúdo das mensagens em crime grave.', '["Assertiva que permite interceptar o conteúdo para qualquer infração erra: restringe-se a crimes graves."]'::jsonb, '[]'::jsonb, '["Artigo 20"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'budapeste' and u.unit_key = 'conven-o-artigo-21'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Jurisdição: cada Parte estabelecerá jurisdição sobre os crimes dos artigos 2 a 11 quando cometidos no seu território, a bordo de embarcação de sua bandeira, a bordo de aeronave registrada conforme suas leis, ou por um nacional seu, se o crime for punível no local do fato ou cometido fora da jurisdição de qualquer Parte. Pode reservar-se o direito de não aplicar os critérios de embarcação, aeronave e nacionalidade. A Parte também estabelece jurisdição quando um suspeito está em seu território e ela não o extradita apenas por sua nacionalidade. A Convenção não exclui outras jurisdições criminais. Havendo mais de uma Parte com jurisdição, devem consultar-se para determinar a mais adequada.', '["Território, embarcação, aeronave e nacionalidade.","Reserva possível para embarcação, aeronave e nacionalidade.","Aut dedere aut judicare: jurisdição se não extradita nacional.","Consulta entre as Partes em caso de conflito."]'::jsonb, '["Quem não extradita por nacionalidade deve ter jurisdição para processar."]'::jsonb, 'O Brasil julga o brasileiro que cometeu crime cibernético no exterior, se o fato for punível lá.', '["Assertiva que exclui a jurisdição pelo critério da nacionalidade do agente erra."]'::jsonb, '[]'::jsonb, '["Artigo 24"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'budapeste' and u.unit_key = 'conven-o-artigo-22'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Princípios gerais da cooperação internacional: as Partes cooperarão entre si, o mais possível, por meio de instrumentos internacionais de cooperação em assuntos penais, de ajustes baseados em legislação uniforme ou de reciprocidade e da legislação interna, para investigações ou procedimentos acerca de crimes de computador, ou para a coleta de provas eletrônicas desses crimes.', '["Cooperação o mais ampla possível.","Instrumentos de cooperação penal, legislação uniforme ou reciprocidade e lei interna.","Foco em crimes de computador e prova eletrônica."]'::jsonb, '["Cooperação ampla, mas conforme os instrumentos e a lei interna."]'::jsonb, 'Dois países cooperam para obter provas digitais de uma fraude.', '["Assertiva que limita a cooperação aos Estados membros do Conselho da Europa erra."]'::jsonb, '[]'::jsonb, '["Artigo 25"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'budapeste' and u.unit_key = 'conven-o-artigo-23'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Extradição: aplica-se aos crimes dos artigos 2 a 11, desde que puníveis nas leis das duas Partes com pena privativa de liberdade máxima de pelo menos um ano, ou mais severa, salvo pena mínima diferente em tratado. Os crimes serão considerados extraditáveis em qualquer tratado existente ou futuro entre as Partes. A Parte que condiciona a extradição a tratado pode usar a Convenção como base legal, e as que não condicionam reconhecerão os crimes como extraditáveis. A extradição sujeita-se às condições da lei da Parte requerida e aos tratados aplicáveis. Se a extradição for recusada somente pela nacionalidade, a Parte requerida deve submeter o caso às suas autoridades para processo.', '["Pena máxima de pelo menos um ano nas duas legislações.","Crimes extraditáveis em tratados existentes e futuros.","A Convenção pode servir de base legal para a extradição.","Recusa por nacionalidade: processar o suspeito."]'::jsonb, '["Dupla tipicidade com pena máxima de pelo menos um ano."]'::jsonb, 'O crime é extraditável se punido, nos dois países, com pena máxima de pelo menos um ano.', '["Assertiva que dispensa a dupla incriminação para a extradição erra: o crime deve ser punível nas duas Partes."]'::jsonb, '[]'::jsonb, '["Artigo 22"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'budapeste' and u.unit_key = 'conven-o-artigo-24'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Princípios gerais da assistência mútua: as Partes prestarão assistência umas às outras o mais possível, para investigações relacionadas a crimes de computador e para obter provas eletrônicas. Cada Parte adotará as medidas para cumprir as obrigações dos Artigos 27 a 35. Em casos urgentes, a assistência pode ser solicitada por meios rápidos, como fax ou e-mail, com segurança e autenticidade, e confirmação formal se exigida. Salvo disposição contrária, a assistência sujeita-se às condições da lei da Parte requerida, mas não se recusa em relação aos crimes dos artigos 2 a 11 apenas por se tratar de simples delito financeiro. A dupla tipicidade considera-se atendida se a conduta é crime nas duas Partes, independentemente da denominação.', '["Assistência mútua o mais ampla possível.","Pedidos urgentes por meios rápidos, com confirmação formal.","Não se recusa a assistência por mero delito financeiro.","Dupla tipicidade pela conduta, e não pelo nome do crime."]'::jsonb, '["Dupla tipicidade avaliada pela CONDUTA."]'::jsonb, 'Um pedido urgente é feito por e-mail seguro e depois confirmado formalmente.', '["Assertiva que exige a mesma denominação do crime nos dois países erra: basta a mesma conduta."]'::jsonb, '[{"termo":"Dupla tipicidade","significado":"O fato deve ser crime nos dois países."}]'::jsonb, '["Artigo 27"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'budapeste' and u.unit_key = 'conven-o-artigo-25'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Informação espontânea: qualquer Parte pode, nos limites de sua legislação interna e de ofício, transmitir a outra informações obtidas por sua própria investigação, quando considerar que podem ajudar a Parte destinatária a iniciar ou levar adiante investigações dos crimes da Convenção ou levar a um pedido de cooperação. Antes de fornecer, a Parte remetente pode pedir sigilo ou uso condicional. Se a destinatária não puder atender, deve notificá-la, que decidirá se fornece mesmo assim. Aceitas as condições, a destinatária é obrigada a cumpri-las.', '["Transmissão de ofício de informações úteis a outra Parte.","Sigilo ou uso condicional podem ser pedidos.","Condições aceitas obrigam a destinatária."]'::jsonb, '["Iniciativa da Parte que possui a informação, sem pedido prévio."]'::jsonb, 'A polícia brasileira repassa a outro país indícios de um ataque que o afeta.', '["Assertiva que exige pedido formal prévio para a informação espontânea erra."]'::jsonb, '[]'::jsonb, '["Artigo 25"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'budapeste' and u.unit_key = 'conven-o-artigo-26'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Procedimentos relativos a pedidos de assistência mútua na falta de acordos internacionais aplicáveis: quando não houver tratados ou acordos entre as Partes, aplicam-se as regras deste artigo. Cada Parte indicará uma autoridade central para enviar e responder pedidos, que se comunicarão diretamente, e informará seus nomes e endereços ao Secretário-Geral do Conselho da Europa, que mantém o cadastro atualizado. Os pedidos serão executados conforme os procedimentos da Parte requerente, salvo incompatibilidade com a lei da requerida. A Parte requerida pode recusar a assistência, entre outras causas, se o pedido se referir a delito político.', '["Aplica-se na falta de tratados ou acordos.","Autoridade central de cada Parte.","Comunicação direta entre autoridades centrais.","Cadastro mantido pelo Secretário-Geral do Conselho da Europa.","Execução conforme procedimentos da requerente, salvo incompatibilidade."]'::jsonb, '["Regra subsidiária: só se aplica se não houver tratado ou acordo."]'::jsonb, 'As autoridades centrais dos dois países trocam diretamente os pedidos de assistência.', '["Assertiva que obriga a passar sempre pelo canal diplomático erra: as autoridades centrais se comunicam diretamente."]'::jsonb, '[{"termo":"Autoridade central","significado":"Órgão designado para enviar e receber pedidos de cooperação."}]'::jsonb, '["Artigo 25"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'budapeste' and u.unit_key = 'conven-o-artigo-27'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Confidencialidade e limitações de uso: na falta de tratado ou acordo entre as Partes, a Parte requerida pode condicionar o fornecimento de informação ou dados à sua manutenção em sigilo ou à sua não utilização para investigações diversas das indicadas no pedido. Se a Parte requerente não puder cumprir as condições, informará à outra, que decidirá se fornece ainda assim. Aceitas as condições, a requerente é obrigada a atendê-las, e a fornecedora pode exigir esclarecimentos sobre o uso feito.', '["Condição de sigilo ou de uso limitado ao pedido.","Aviso se a requerente não puder cumprir.","Condição aceita obriga a requerente.","Esclarecimentos sobre o uso."]'::jsonb, '["Princípio da especialidade: uso limitado à finalidade do pedido."]'::jsonb, 'O país que fornece dados exige que só sejam usados na investigação indicada.', '["Assertiva que permite usar livremente os dados recebidos em outras investigações erra: pode haver condição de não utilização."]'::jsonb, '[]'::jsonb, '["Artigo 27"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'budapeste' and u.unit_key = 'conven-o-artigo-28'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Conservação expedita de dados armazenados em computador: qualquer Parte pode pedir a outra que obtenha a rápida conservação de dados armazenados em sistema no território desta, em relação aos quais pretende apresentar pedido de assistência para busca, apreensão ou revelação. O pedido deve especificar a autoridade, o crime e um breve resumo dos fatos, os dados e sua relação com o crime, as informações sobre o detentor ou o local, a necessidade de conservação e a intenção de pedir assistência. A Parte requerida adotará as medidas para conservar os dados com presteza, sem exigir dupla tipicidade como condição para a conservação.', '["Pedido de conservação rápida de dados em outro país.","Requisitos do pedido: autoridade, crime, dados, detentor, necessidade e intenção de pedir assistência.","Dupla tipicidade não é exigida para conservar."]'::jsonb, '["Conservação NÃO exige dupla tipicidade."]'::jsonb, 'O Brasil pede a outro país que preserve os registros de um servidor enquanto formaliza o pedido de acesso.', '["Assertiva que exige dupla tipicidade para a conservação de dados erra."]'::jsonb, '[]'::jsonb, '["Artigo 16"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'budapeste' and u.unit_key = 'conven-o-artigo-29'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Revelação expedita de dados de tráfego conservados: quando, ao executar pedido de conservação, a Parte requerida descobrir que provedor de outro Estado participou da transmissão, entregará rapidamente à requerente dados de tráfego suficientes para identificar o provedor e o caminho da comunicação. A revelação só pode ser recusada se o pedido se referir a crime político ou conexo, ou se puder prejudicar a soberania, a segurança, a ordem pública ou outros interesses essenciais.', '["Revelação rápida de dados suficientes para identificar o provedor e o caminho.","Recusa só por crime político ou prejuízo à soberania, segurança ou ordem pública."]'::jsonb, '["Hipóteses de recusa são restritas."]'::jsonb, 'A Parte requerida informa qual provedor de outro país transmitiu a comunicação.', '["Assertiva que permite recusar a revelação por qualquer motivo erra: as hipóteses são restritas."]'::jsonb, '[]'::jsonb, '["Artigo 29"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'budapeste' and u.unit_key = 'conven-o-artigo-30'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Assistência mútua em relação ao acesso a dados armazenados: qualquer Parte pode pedir a outra que realize busca, acesso, apreensão, guarda ou revelação de dados armazenados em sistema de computador no território desta, inclusive dados conservados. A Parte requerida responderá pelos instrumentos, acordos e leis internacionais aplicáveis. O pedido receberá resposta rápida se houver motivos para supor que dados importantes estão especialmente vulneráveis a perda ou modificação, ou se os instrumentos dispuserem de forma diferente quanto à cooperação expedita.', '["Pedido de busca, acesso, apreensão ou revelação de dados.","Resposta rápida se os dados estão vulneráveis.","Segue os instrumentos internacionais aplicáveis."]'::jsonb, '["Resposta rápida quando há risco de perda ou modificação."]'::jsonb, 'O Brasil pede a outro país a apreensão de dados de um servidor que podem ser apagados.', '["Assertiva que fixa resposta sempre lenta, sem prioridade para dados vulneráveis, erra."]'::jsonb, '[]'::jsonb, '["Artigo 29"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'budapeste' and u.unit_key = 'conven-o-artigo-31'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Acesso transfronteiriço a dados armazenados mediante consentimento ou em sistema de acesso público: uma Parte poderá, sem a autorização de outra, acessar dados de computador disponíveis ao público (fonte aberta), onde quer que estejam; ou acessar ou receber, por sistema em seu território, dados armazenados no território de outra Parte, se obtiver o consentimento legítimo e voluntário de pessoa com autoridade legal para revelá-los.', '["Acesso a fontes abertas sem autorização.","Acesso a dados em outra Parte com consentimento legítimo e voluntário de quem tem autoridade para revelar."]'::jsonb, '["Sem autorização do outro Estado só em fonte aberta ou com consentimento voluntário."]'::jsonb, 'A polícia acessa uma página pública hospedada no exterior sem pedir autorização ao outro país.', '["Assertiva que permite acessar dados privados de outro país sem qualquer consentimento erra."]'::jsonb, '[{"termo":"Fonte aberta","significado":"Informação disponível ao público."}]'::jsonb, '["Artigo 31"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'budapeste' and u.unit_key = 'conven-o-artigo-32'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Assistência mútua na interceptação de dados de tráfego em tempo real: as Partes se concederão assistência na interceptação, em tempo real, de dados de tráfego vinculados a comunicação específica transmitida em seu território por sistema de computador, conforme as condições e procedimentos da legislação interna. Cada Parte prestará essa assistência pelo menos em relação aos crimes para os quais a interceptação de dados em tempo real seria possível em fatos similares de jurisdição nacional.', '["Assistência na interceptação de dados de tráfego em tempo real.","Regida pela lei interna.","Ao menos para crimes que admitiriam a medida em caso nacional similar."]'::jsonb, '["Dados de TRÁFEGO (o conteúdo está no Artigo 34)."]'::jsonb, 'Um país ajuda outro a acompanhar em tempo real os dados de tráfego de uma comunicação específica.', '["Assertiva que obriga a assistência para qualquer crime erra: vale ao menos para crimes que admitiriam a medida no direito interno."]'::jsonb, '[]'::jsonb, '["Artigo 34"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'budapeste' and u.unit_key = 'conven-o-artigo-33'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Assistência mútua em relação à interceptação do conteúdo de comunicações: as Partes se concederão assistência na interceptação ou gravação, em tempo real, do conteúdo de comunicações específicas transmitidas por sistema de computador, nas mesmas hipóteses permitidas pelos tratados aplicáveis e pelas respectivas legislações internas.', '["Assistência na interceptação do conteúdo em tempo real.","Mesmas hipóteses dos tratados e da lei interna."]'::jsonb, '["Conteúdo: depende dos tratados e das leis internas."]'::jsonb, 'Um país auxilia outro a gravar o conteúdo de uma comunicação específica, quando as leis permitem.', '["Assertiva que dispensa os limites da lei interna na interceptação de conteúdo erra."]'::jsonb, '[]'::jsonb, '["Artigo 33"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'budapeste' and u.unit_key = 'conven-o-artigo-34'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Sistema de plantão 24 por 7: cada Parte indicará um órgão de contato disponível 24 horas por dia, 7 dias por semana, para assegurar assistência imediata em investigações de crimes de computador e na obtenção de provas eletrônicas, incluindo o suporte técnico, a conservação de dados e a coleta de provas, informação jurídica e localização de suspeitos. O órgão de contato deve se comunicar rapidamente com o de outra Parte e coordenar-se com as autoridades de assistência mútua e extradição. Cada Parte assegurará pessoal treinado e bem equipado.', '["Ponto de contato 24 horas por dia, 7 dias por semana.","Suporte técnico, conservação de dados, coleta de provas e localização de suspeitos.","Comunicação rápida com outras Partes.","Pessoal treinado e equipado."]'::jsonb, '["Plantão 24/7."]'::jsonb, 'A polícia estrangeira aciona o ponto de contato brasileiro de madrugada para preservar dados.', '["Assertiva que limita o ponto de contato ao horário comercial erra: é 24 horas por dia, 7 dias por semana."]'::jsonb, '[]'::jsonb, '["Artigos 29 e 30"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'budapeste' and u.unit_key = 'conven-o-artigo-35'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Assinatura e vigência: a Convenção está aberta à assinatura dos Estados membros do Conselho da Europa e dos não membros que participaram de sua elaboração, sujeita à ratificação, aceitação ou aprovação, com depósito junto ao Secretário-Geral. Entra em vigor no primeiro dia do mês seguinte a três meses da data em que cinco Estados, incluindo pelo menos três membros do Conselho da Europa, tiverem expressado sua vontade de se obrigar. Para os demais signatários, entra em vigor no primeiro dia do mês seguinte a três meses da expressão de vontade.', '["Assinatura aberta a membros e a não membros que participaram da elaboração.","Ratificação, aceitação ou aprovação.","Vigência após cinco Estados, com pelo menos três membros do Conselho da Europa.","Três meses para os demais."]'::jsonb, '["Cinco Estados, entre eles três membros do Conselho da Europa."]'::jsonb, 'A Convenção só passou a vigorar com cinco Estados, incluindo três membros do Conselho.', '["Assertiva que fixa em dez Estados o número mínimo para a vigência erra: são cinco."]'::jsonb, '[]'::jsonb, '["Artigo 37"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'budapeste' and u.unit_key = 'conven-o-artigo-36'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Adesão à Convenção: depois da vigência, o Conselho de Ministros do Conselho da Europa, após consulta e com o consentimento unânime dos Estados signatários, pode convidar Estado não membro que não tenha participado da elaboração para aderir. Para os Estados que aderirem, a Convenção entra em vigor no primeiro dia do mês seguinte a três meses do depósito do instrumento de adesão.', '["Convite pelo Conselho de Ministros.","Consentimento unânime dos Estados signatários.","Vigência após três meses do depósito."]'::jsonb, '["Convite exige consentimento unânime dos signatários."]'::jsonb, 'O Brasil aderiu à Convenção após convite formal do Conselho de Ministros.', '["Assertiva que permite a adesão de qualquer Estado sem convite erra."]'::jsonb, '[]'::jsonb, '["Artigo 36"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'budapeste' and u.unit_key = 'conven-o-artigo-37'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Aplicação territorial: qualquer Estado pode, ao assinar ou depositar o instrumento, especificar os territórios em que a Convenção será aplicável. Pode, posteriormente, por declaração ao Secretário-Geral, estendê-la a outro território, que entra em vigor no primeiro dia do mês seguinte a três meses do recebimento. A declaração pode ser retirada por notificação, com eficácia no primeiro dia do mês seguinte a três meses do recebimento.', '["Especificação do território na assinatura ou depósito.","Extensão posterior por declaração.","Retirada por notificação, com prazo de três meses."]'::jsonb, '["Três meses de prazo para extensão e retirada."]'::jsonb, 'Um Estado estende a Convenção a um território ultramarino por declaração.', '["Assertiva que torna a extensão territorial imediata erra: depende de prazo de três meses."]'::jsonb, '[]'::jsonb, '["Artigo 36"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'budapeste' and u.unit_key = 'conven-o-artigo-38'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Efeitos da Convenção: o objetivo é complementar os tratados e acordos bilaterais ou multilaterais aplicáveis entre as Partes, incluindo as convenções europeias sobre extradição e assistência mútua em assuntos penais. Se duas ou mais Partes já tiverem acordo sobre esses assuntos, podem aplicá-lo, mas de forma compatível com os objetivos e princípios da Convenção. Nenhum artigo afetará outros direitos, restrições, obrigações e responsabilidades de uma Parte.', '["A Convenção complementa outros tratados.","Acordos anteriores podem ser aplicados, de forma compatível com a Convenção.","Não afeta outros direitos e obrigações da Parte."]'::jsonb, '["Natureza COMPLEMENTAR."]'::jsonb, 'Países com tratado de assistência mútua mantêm o acordo, sem contrariar a Convenção.', '["Assertiva que revoga os tratados anteriores sobre o tema erra: a Convenção os complementa."]'::jsonb, '[]'::jsonb, '["Artigo 24"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'budapeste' and u.unit_key = 'conven-o-artigo-39'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Declarações: por notificação escrita ao Secretário-Geral do Conselho da Europa, qualquer Estado pode, ao assinar ou depositar o instrumento, declarar que se valerá da faculdade de exigir elementos complementares, como previsto nos artigos 2, 3, 6 parágrafo 1.b, 7, 9 parágrafo 3 e 27 parágrafo 9.e.', '["Declaração de exigência de elementos complementares.","Aplicável a artigos específicos."]'::jsonb, '["Declarações são distintas de reservas."]'::jsonb, 'Um Estado declara que exigirá violação de medidas de segurança no acesso ilegal.', '["Assertiva que permite declarações sobre qualquer artigo erra: apenas os indicados."]'::jsonb, '[]'::jsonb, '["Artigo 42"]'::jsonb, 'under_review', 'claude'
