insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Cláusula federativa: um Estado federal pode reservar-se o direito de assumir as obrigações do capítulo II conforme os princípios fundamentais de suas relações entre o governo central e as unidades constitutivas, desde que possa cooperar nos termos do capítulo III. Essa reserva não pode excluir ou diminuir substancialmente suas obrigações de dispor sobre as medidas do capítulo II, e o Estado deve prever amplo sistema de persecução criminal. Quanto às matérias de competência dos Estados federados, o governo federal informará suas autoridades, dará opinião favorável e as encorajará a dar efeito às disposições.', '["Reserva própria dos Estados federais.","Não pode esvaziar as obrigações do capítulo II.","Governo federal incentiva os entes federados."]'::jsonb, '["Cláusula aplicável a Estados federais, como o Brasil."]'::jsonb, 'Um Estado federal adapta as obrigações à repartição de competências, sem esvaziá-las.', '["Assertiva que permite ao Estado federal excluir totalmente as obrigações do capítulo II erra."]'::jsonb, '[]'::jsonb, '["Artigo 42"]'::jsonb, 'under_review', 'claude'
