insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Reservas: por notificação escrita ao Secretário-Geral, qualquer Estado poderá, ao assinar ou depositar o instrumento, declarar que se valerá das reservas previstas no Artigo 4 parágrafo 2, Artigo 6 parágrafo 3, Artigo 9 parágrafo 4, Artigo 10 parágrafo 3, Artigo 11 parágrafo 3, Artigo 14 parágrafo 3, Artigo 22 parágrafo 2, Artigo 29 parágrafo 4 e Artigo 41 parágrafo 1. Nenhuma outra reserva poderá ser apresentada.', '["Lista fechada de reservas.","Nenhuma outra reserva é admitida."]'::jsonb, '["Rol TAXATIVO de reservas."]'::jsonb, 'O Estado só pode fazer as reservas expressamente listadas.', '["Assertiva que permite reservas livres erra: nenhuma outra reserva é admitida."]'::jsonb, '[{"termo":"Reserva","significado":"Declaração que exclui ou modifica o efeito de certa disposição do tratado."}]'::jsonb, '["Artigo 43"]'::jsonb, 'under_review', 'claude'
