insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Status e retirada de reservas: a Parte que tenha apresentado reserva pode retirá-la no todo ou em parte por notificação ao Secretário-Geral, com efeito na data indicada, se posterior ao recebimento. Deverá retirá-la assim que as circunstâncias permitirem. O Secretário-Geral pode periodicamente entrevistar-se com as Partes que tenham reservas, tendo em vista sua retirada.', '["Retirada total ou parcial por notificação.","Dever de retirar quando as circunstâncias permitirem.","Consultas periódicas do Secretário-Geral."]'::jsonb, '["Retirada pode ter efeito em data posterior."]'::jsonb, 'O Estado retira sua reserva por notificação ao Secretário-Geral.', '["Assertiva que torna as reservas permanentes erra: devem ser retiradas quando as circunstâncias permitirem."]'::jsonb, '[]'::jsonb, '["Artigo 42"]'::jsonb, 'under_review', 'claude'
