insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Emendas: podem ser propostas por qualquer Parte, e o Secretário-Geral as leva ao conhecimento dos Estados membros do Conselho da Europa, dos não membros que participaram da elaboração e dos aderentes. A proposta é submetida ao Comitê Europeu para os Problemas Criminais (CDPC), que emite parecer, e ao Conselho de Ministros, que pode adotá-la após consultar os Estados não membros que sejam Partes. A emenda adotada é encaminhada às Partes para aceitação e entra em vigor 30 dias depois de todas informarem sua aceitação.', '["Qualquer Parte pode propor.","Parecer do CDPC e decisão do Conselho de Ministros.","Aceitação pelas Partes.","Vigência 30 dias após a aceitação de todas."]'::jsonb, '["A emenda só vale após a aceitação de TODAS as Partes."]'::jsonb, 'Uma emenda só entra em vigor depois que todas as Partes a aceitam.', '["Assertiva que permite a vigência da emenda com aceitação da maioria das Partes erra: exige todas."]'::jsonb, '[]'::jsonb, '["Artigo 46"]'::jsonb, 'under_review', 'claude'
