insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Solução de controvérsias: o Comitê Europeu para os Problemas Criminais (CDPC) será informado das interpretações e da aplicação da Convenção. Em controvérsias entre Partes sobre sua interpretação ou aplicação, estas buscarão a composição por negociação ou outro meio pacífico à sua escolha, inclusive submeter ao CDPC, a tribunal arbitral cujas decisões sejam imperativas ou à Corte Internacional de Justiça, como combinado pelas Partes.', '["CDPC é informado da aplicação.","Negociação ou outro meio pacífico.","Possibilidade de CDPC, arbitragem ou Corte Internacional de Justiça."]'::jsonb, '["Meios pacíficos, à escolha das Partes."]'::jsonb, 'Dois Estados em disputa submetem o caso à arbitragem, se concordarem.', '["Assertiva que impõe a jurisdição obrigatória da Corte Internacional de Justiça erra: depende do que as Partes combinarem."]'::jsonb, '[]'::jsonb, '["Artigo 46"]'::jsonb, 'under_review', 'claude'
